package com.primehr.performancemanagement.application;
import com.primehr.integration.administrative.PermissionDataScope;import com.primehr.performancemanagement.api.PerformanceCalibrationDtos.*;import com.primehr.performancemanagement.api.PerformanceRatingDtos.AssessmentResponse;import com.primehr.performancemanagement.domain.*;import com.primehr.performancemanagement.infrastructure.*;import com.primehr.shared.audit.PrimeHrAuditService;import com.primehr.shared.exception.*;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Service@Transactional public class PerformanceCalibrationServiceImpl implements PerformanceCalibrationService{
 private final PerformanceCalibrationCaseRepository cases;private final PerformanceCalibrationParticipantRepository participants;private final PerformanceCalibrationDecisionRepository decisions;private final PerformanceFinalRatingRepository finals;private final PerformanceRatingCaseRepository ratings;private final PerformanceRatingAssessmentRepository assessments;private final PerformancePolicyVersionRepository policies;private final PerformanceManagementTeamRepository teams;private final PerformanceManagementTeamMemberRepository members;private final PerformanceCycleMilestoneRepository milestones;private final PerformanceRatingActionRepository actions;private final PerformanceRatingService ratingService;private final PerformanceInterventionService interventionService;private final PrimeHrAuditService audit;
 public PerformanceCalibrationServiceImpl(PerformanceCalibrationCaseRepository cases,PerformanceCalibrationParticipantRepository participants,PerformanceCalibrationDecisionRepository decisions,PerformanceFinalRatingRepository finals,PerformanceRatingCaseRepository ratings,PerformanceRatingAssessmentRepository assessments,PerformancePolicyVersionRepository policies,PerformanceManagementTeamRepository teams,PerformanceManagementTeamMemberRepository members,PerformanceCycleMilestoneRepository milestones,PerformanceRatingActionRepository actions,PerformanceRatingService ratingService,PerformanceInterventionService interventionService,PrimeHrAuditService audit){this.cases=cases;this.participants=participants;this.decisions=decisions;this.finals=finals;this.ratings=ratings;this.assessments=assessments;this.policies=policies;this.teams=teams;this.members=members;this.milestones=milestones;this.actions=actions;this.ratingService=ratingService;this.interventionService=interventionService;this.audit=audit;}
 @Override public CalibrationResponse open(String agency,String ratingId,OpenInput in,String actor,String correlation){PerformanceRatingCase rating=rating(agency,ratingId);var existing=cases.findByAgencyIdAndRatingCaseId(agency,ratingId);if(existing.isPresent())return response(agency,existing.get());check(rating.getVersion(),in.ratingRecordVersion());PerformancePolicyVersion policy=policy(agency,rating.getPolicyVersionId());if(!policy.isRequiresPmtCalibration())throw new IllegalStateException("The exact performance policy does not require PMT calibration");if(rating.getStatus()!=PerformanceRatingCase.Status.SUPERVISOR_SUBMITTED)throw new IllegalStateException("A submitted supervisor assessment is required");window(agency,rating.getCycleId(),PerformanceCycleMilestone.Type.CALIBRATION_DUE,in.overrideWindow(),in.reason());PerformanceRatingAssessment supervisor=current(agency,ratingId,PerformanceRatingAssessment.Type.SUPERVISOR);LocalDate day=LocalDate.now(ZoneId.of("Asia/Manila"));PerformanceManagementTeam team=effectiveTeam(agency);List<PerformanceManagementTeamMember> roster=members.findByAgencyIdAndPmtIdOrderByEffectiveFromAscRoleAscEmployeeNoAsc(agency,team.getId()).stream().filter(x->x.effectiveOn(day)).toList();if(roster.stream().noneMatch(x->x.getEmployeeNo().equalsIgnoreCase(actor)))throw new AccessDeniedException("Effective PMT membership is required");int voters=(int)roster.stream().filter(x->eligible(x,rating)).count();PerformanceCalibrationCase value=cases.saveAndFlush(new PerformanceCalibrationCase(agency,ratingId,supervisor.getId(),team.getId(),team.getRosterRevision(),voters,actor,Instant.now()));for(var member:roster){boolean eligible=eligible(member,rating);String conflict=member.getEmployeeNo().equalsIgnoreCase(rating.getOwnerEmployeeNo())?"RATING_SUBJECT":member.getEmployeeNo().equalsIgnoreCase(rating.getSupervisorEmployeeNo())?"ASSIGNED_RATER":null;participants.save(new PerformanceCalibrationParticipant(agency,value.getId(),member,eligible,conflict));}rating.calibrationOpened();ratings.saveAndFlush(rating);record(agency,ratingId,value.getId(),"OPEN_CALIBRATION",in.idempotencyKey(),actor,in.reason());audit.record(agency,"OPEN_PERFORMANCE_CALIBRATION","SPMS_CALIBRATION_CASE",value.getId(),1,value.getVersion(),null,response(agency,value),in.reason(),correlation);return response(agency,value);}
 @Override@Transactional(readOnly=true)public CalibrationResponse get(String agency,String id,String actor){PerformanceCalibrationCase value=calibration(agency,id);member(agency,value,actor,false);return response(agency,value);}
 @Override public CalibrationResponse propose(String agency,String id,ProposalInput in,String actor,String correlation){PerformanceCalibrationCase value=calibration(agency,id);PerformanceCalibrationParticipant author=member(agency,value,actor,false);if(recorded(agency,value.getRatingCaseId(),in.idempotencyKey()))return response(agency,value);check(value.getVersion(),in.calibrationRecordVersion());if(value.getStatus()!=PerformanceCalibrationCase.Status.OPEN)throw new IllegalStateException("Calibration proposal is not open");PerformanceRatingCase rating=rating(agency,value.getRatingCaseId());window(agency,rating.getCycleId(),PerformanceCycleMilestone.Type.CALIBRATION_DUE,in.overrideWindow(),in.rationale());AssessmentResponse proposal=ratingService.createCalibrationAssessment(agency,rating.getId(),in.rationale(),in.items(),actor,correlation);int independentVoters=value.getEligibleVoters()-(author.isDecisionEligible()?1:0);value.proposalSubmitted(proposal.id(),independentVoters);value=cases.saveAndFlush(value);record(agency,rating.getId(),value.getId(),"SUBMIT_CALIBRATION_PROPOSAL",in.idempotencyKey(),actor,in.rationale());return response(agency,value);}
 @Override public CalibrationResponse decide(String agency,String id,DecisionInput in,String actor,String correlation){PerformanceCalibrationCase value=calibration(agency,id);PerformanceCalibrationParticipant participant=member(agency,value,actor,true);if(recorded(agency,value.getRatingCaseId(),in.idempotencyKey()))return response(agency,value);PerformanceRatingAssessment proposal=ratingService.assessmentEntity(agency,value.getProposalAssessmentId());if(proposal.getAuthorEmployeeNo().equalsIgnoreCase(actor))throw new AccessDeniedException("Calibration proposal author cannot decide the same adjustment");check(value.getVersion(),in.calibrationRecordVersion());if(value.getStatus()!=PerformanceCalibrationCase.Status.PROPOSAL_SUBMITTED)throw new IllegalStateException("Calibration is not awaiting decisions");if(decisions.findByAgencyIdAndCalibrationCaseIdAndEmployeeNoIgnoreCase(agency,id,actor).isPresent())throw new IllegalStateException("PMT member has already decided this calibration");decisions.saveAndFlush(new PerformanceCalibrationDecision(agency,id,participant.getEmployeeNo(),in.decision(),in.rationale(),Instant.now()));value.decisionRecorded();List<PerformanceCalibrationDecision> recordedDecisions=decisions.findByAgencyIdAndCalibrationCaseId(agency,id);long approvals=recordedDecisions.stream().filter(x->x.getDecision()==PerformanceCalibrationDecision.Decision.APPROVE).count();long rejections=recordedDecisions.stream().filter(x->x.getDecision()==PerformanceCalibrationDecision.Decision.REJECT).count();if(approvals>=value.getQuorumRequired()){value.approve();PerformanceRatingCase rating=rating(agency,value.getRatingCaseId());rating.readyForFinalization();ratings.saveAndFlush(rating);}else if(rejections>=value.getQuorumRequired()){value.reject();}value=cases.saveAndFlush(value);record(agency,value.getRatingCaseId(),id,"CALIBRATION_"+in.decision(),in.idempotencyKey(),actor,in.rationale());audit.record(agency,"DECIDE_PERFORMANCE_CALIBRATION","SPMS_CALIBRATION_CASE",id,1,value.getVersion(),null,response(agency,value),in.rationale(),correlation);return response(agency,value);}
 @Override public FinalRatingResponse finalizeRating(String agency,String ratingId,FinalizeInput in,String actor,String correlation){PerformanceRatingCase rating=rating(agency,ratingId);var existingFinal=finals.findTopByAgencyIdAndRatingCaseIdOrderByRevisionNoDesc(agency,ratingId);if(existingFinal.isPresent())return finalResponse(existingFinal.get());check(rating.getVersion(),in.ratingRecordVersion());PerformancePolicyVersion policy=policy(agency,rating.getPolicyVersionId());window(agency,rating.getCycleId(),PerformanceCycleMilestone.Type.FINALIZATION_DUE,in.overrideWindow(),in.reason());PerformanceCalibrationCase calibration=null;PerformanceRatingAssessment source;if(policy.isRequiresPmtCalibration()){calibration=cases.findByAgencyIdAndRatingCaseId(agency,ratingId).orElseThrow(()->new IllegalStateException("Approved calibration is required"));member(agency,calibration,actor,true);if(calibration.getStatus()!=PerformanceCalibrationCase.Status.APPROVED)throw new IllegalStateException("Approved calibration is required");source=ratingService.assessmentEntity(agency,calibration.getProposalAssessmentId());if(source.getAuthorEmployeeNo().equalsIgnoreCase(actor))throw new AccessDeniedException("Calibration proposal author cannot finalize the same rating");}else{PerformanceManagementTeam team=effectiveTeam(agency);if(!members.findByAgencyIdAndPmtIdOrderByEffectiveFromAscRoleAscEmployeeNoAsc(agency,team.getId()).stream().anyMatch(x->x.effectiveOn(LocalDate.now(ZoneId.of("Asia/Manila")))&&x.getEmployeeNo().equalsIgnoreCase(actor)&&x.isVoting()&&!x.getEmployeeNo().equalsIgnoreCase(rating.getOwnerEmployeeNo())&&!x.getEmployeeNo().equalsIgnoreCase(rating.getSupervisorEmployeeNo())))throw new AccessDeniedException("An effective non-conflicted voting PMT member must finalize the rating");rating.readyForFinalization();source=current(agency,ratingId,PerformanceRatingAssessment.Type.SUPERVISOR);}PerformanceFinalRating result=finals.saveAndFlush(new PerformanceFinalRating(agency,ratingId,calibration==null?null:calibration.getId(),source,actor,Instant.now()));rating.finalized();ratings.saveAndFlush(rating);if(calibration!=null){calibration.finalized();cases.saveAndFlush(calibration);}interventionService.evaluate(agency,result,actor,correlation);record(agency,ratingId,result.getId(),"FINALIZE_RATING",in.idempotencyKey(),actor,in.reason());FinalRatingResponse after=finalResponse(result);audit.record(agency,"FINALIZE_PERFORMANCE_RATING","SPMS_FINAL_RATING",result.getId(),1,result.getVersion(),null,after,in.reason(),correlation);return after;}
 private boolean eligible(PerformanceManagementTeamMember m,PerformanceRatingCase r){return m.isVoting()&&m.getRole()!=PerformanceManagementTeamMember.Role.SECRETARIAT&&m.getRole()!=PerformanceManagementTeamMember.Role.TECHNICAL_SUPPORT&&!m.getEmployeeNo().equalsIgnoreCase(r.getOwnerEmployeeNo())&&!m.getEmployeeNo().equalsIgnoreCase(r.getSupervisorEmployeeNo());}private PerformanceCalibrationParticipant member(String a,PerformanceCalibrationCase c,String actor,boolean decision){PerformanceCalibrationParticipant p=participants.findByAgencyIdAndCalibrationCaseIdAndEmployeeNoIgnoreCase(a,c.getId(),actor).orElseThrow(()->new AccessDeniedException("Effective PMT membership is required"));if(decision&&!p.isDecisionEligible())throw new AccessDeniedException("Conflicted or non-voting PMT member cannot decide this calibration");return p;}private PerformanceManagementTeam effectiveTeam(String a){LocalDate d=LocalDate.now(ZoneId.of("Asia/Manila"));List<PerformanceManagementTeam> effective=teams.findAll().stream().filter(x->x.getAgencyId().equals(a)&&x.effectiveOn(d)).toList();if(effective.isEmpty())throw new IllegalStateException("No effective PMT is configured");if(effective.size()>1)throw new IllegalStateException("Multiple effective PMTs are configured; correct the PMT effectivity dates");return effective.get(0);}
 private void window(String a,String cycle,PerformanceCycleMilestone.Type type,boolean override,String reason){PerformanceCycleMilestone m=milestones.findByAgencyIdAndCycleIdOrderByDisplayOrderAsc(a,cycle).stream().filter(x->x.getType()==type).findFirst().orElseThrow(()->new IllegalArgumentException(type+" milestone is required"));Instant now=Instant.now(),end=m.getEndsAt()==null?m.getStartsAt():m.getEndsAt();if((now.isBefore(m.getStartsAt())||now.isAfter(end))&&!override)throw new IllegalArgumentException("Action is outside the configured "+type+" window");if(override&&(reason==null||reason.isBlank()))throw new IllegalArgumentException("A window override reason is required");}
 private CalibrationResponse response(String a,PerformanceCalibrationCase c){List<ParticipantResponse> ps=participants.findByAgencyIdAndCalibrationCaseId(a,c.getId()).stream().map(x->new ParticipantResponse(x.getEmployeeNo(),x.getEmployeeName(),x.getMemberRole(),x.isVoting(),x.isDecisionEligible(),x.getConflictReason())).toList();List<DecisionResponse> ds=decisions.findByAgencyIdAndCalibrationCaseId(a,c.getId()).stream().map(x->new DecisionResponse(x.getEmployeeNo(),x.getDecision().name(),x.getRationale(),x.getDecidedAt())).toList();AssessmentResponse proposal=c.getProposalAssessmentId()==null?null:ratingService.get(a,c.getRatingCaseId(),c.getOpenedBy(),PermissionDataScope.AGENCY_WIDE).assessments().stream().filter(x->x.id().equals(c.getProposalAssessmentId())).findFirst().orElse(null);return new CalibrationResponse(c.getId(),c.getRatingCaseId(),c.getSupervisorAssessmentId(),c.getPmtId(),c.getRosterRevision(),c.getEligibleVoters(),c.getQuorumRequired(),c.getDecisionCount(),c.getProposalAssessmentId(),c.getStatus().name(),c.getOpenedBy(),c.getOpenedAt(),c.getVersion(),ps,ds,proposal);}private FinalRatingResponse finalResponse(PerformanceFinalRating x){return new FinalRatingResponse(x.getId(),x.getRatingCaseId(),x.getRevisionNo(),x.getSourceAssessmentId(),x.getCalibrationCaseId(),x.getRawScore(),x.getRoundedScore(),x.getRatingBandId(),x.getRatingLabel(),x.getCalculationFingerprint(),x.getFinalizedBy(),x.getFinalizedAt(),x.getVersion());}
 private PerformanceRatingCase rating(String a,String id){return ratings.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Performance rating case not found"));}private PerformanceCalibrationCase calibration(String a,String id){return cases.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Performance calibration case not found"));}private PerformancePolicyVersion policy(String a,String id){return policies.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Performance policy not found"));}private PerformanceRatingAssessment current(String a,String c,PerformanceRatingAssessment.Type t){return assessments.findByAgencyIdAndRatingCaseIdOrderByCreatedAtAsc(a,c).stream().filter(x->x.getType()==t&&x.getStatus()==PerformanceRatingAssessment.Status.SUBMITTED).reduce((x,y)->y).orElseThrow(()->new IllegalStateException("Submitted "+t+" assessment is required"));}private boolean recorded(String a,String c,String key){return actions.findByAgencyIdAndRatingCaseIdAndRequestKey(a,c,key).isPresent();}private void record(String a,String c,String subject,String type,String key,String actor,String reason){if(!recorded(a,c,key))actions.save(new PerformanceRatingAction(a,c,subject,type,key,actor,reason,Instant.now()));}private static void check(long actual,Long expected){if(expected==null||actual!=expected)throw new OptimisticConflictException("Expected recordVersion "+expected+" but current version is "+actual);}
}
